import{_ as r,o as a,c as t,a5 as s}from"./chunks/framework.CslsFoWx.js";const n="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/01-perf-catalogue-reel.png",o="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/02-catalogue-50k-recherche.png",c="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/03-perf-catalogue-50k.png",d="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/04-recherche-sans-accent-pates.png",i="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/05-AVANT-scans-perdus-dans-recherche.png",u="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/06-APRES-12-scans-recherche-focalisee.png",A=JSON.parse('{"title":"Captures — Mesure &lt; 100 ms par action caissier, app Android (2026-10-29)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-10-29-mesure-100ms-android.md","filePath":"generated/preuves/2026-10-29-mesure-100ms-android.md","lastUpdated":null}'),l={name:"preuves/2026-10-29-mesure-100ms-android.md"};function p(m,e,h,g,f,b){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="captures-—-mesure-lt-100-ms-par-action-caissier-app-android-2026-10-29" tabindex="-1">Captures — Mesure &lt; 100 ms par action caissier, app Android (2026-10-29) <a class="header-anchor" href="#captures-—-mesure-lt-100-ms-par-action-caissier-app-android-2026-10-29" aria-label="Permalink to &quot;Captures — Mesure &amp;lt; 100 ms par action caissier, app Android (2026-10-29)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-10-29-mesure-100ms-android</code> · 6 image(s) · 0 trace(s)</p><div><p>Lot : intégration Android de l&#39;instrumentation <code>:shared</code> (spec 00 §6.1, RG-SALE-01 : p95 &lt; 100 ms de l&#39;entrée à l&#39;état d&#39;écran mis à jour ; RG-CAT-70 : catalogue de référence 50 000 produits). <code>ActionLatencyRecorder</code> UNIQUE dans <code>AppContainer</code> (dépassements journalisés <code>Log.w(&quot;PosPerf&quot;, …)</code>), actions mesurées dans les ViewModels : SCAN, SEARCH, QUICK_BUTTON, LIST_TAP, QUANTITY (+ / −), CHECKOUT. Listes de l&#39;écran de vente BORNÉES à 100 (<code>firstActive</code> / <code>search</code> / <code>activeOfCategory</code>, boutons rapides via <code>productsByIds</code>) avec la ligne « 100 premiers résultats — affinez la recherche ». Écran « Performance » : menu ⋮ → Performance.</p><h2 id="environnement-—-a-lire-avant-les-chiffres" tabindex="-1">Environnement — à lire avant les chiffres <a class="header-anchor" href="#environnement-—-a-lire-avant-les-chiffres" aria-label="Permalink to &quot;Environnement — à lire avant les chiffres&quot;">​</a></h2><ul><li><strong>Émulateur</strong> <code>sdk_gphone64_arm64</code>, Android 16, <strong>1 vCPU</strong>, 4 Go, sur un Mac <strong>Apple M1 16 Go</strong> SURCHARGÉ pendant les mesures : swap hôte ≈ 10 Go / 10–12 Go, charge moyenne ≈ 25 (Xcode/simulateur iOS + lldb d&#39;un autre agent, Docker, démons Gradle). Le thread principal de l&#39;app a passé <strong>23 s en file d&#39;attente CPU pour 0,8 s d&#39;exécution</strong> (schedstat d&#39;une trace ANR), et plusieurs ANR « input dispatching timed out » ont été levés, y compris par System UI. Ce n&#39;est <strong>PAS</strong> un matériel milieu de gamme : les chiffres ci-dessous sont un majorant pessimiste et bruité, pas une mesure de référence.</li><li>Captures prises sur un <strong>build release</strong> (non débogable, R8 désactivé) signé avec la clé de debug et installé par <code>adb install -r</code> (données et appairage conservés), puis compilé AOT (<code>cmd package compile -m speed</code>). Le build debug tourne dans l&#39;interpréteur ART (débogable) et donnait des chiffres sans rapport avec la cible (bouton rapide jusqu&#39;à 2,6 s, recherche jusqu&#39;à 3,2 s). <strong>À la fin, le build debug a été réinstallé</strong> (<code>install -r</code>) : l&#39;app reste appairée au magasin « Épicerie Omar Centre ».</li><li>Serveur arrêté : la caisse travaille hors ligne (offline-first). AUCUN encaissement effectué pendant les captures.</li><li>La mesure s&#39;arrête quand l&#39;état d&#39;écran est posé par le ViewModel (thread principal) ; la recomposition et le rendu de la frame suivante n&#39;y sont pas inclus.</li></ul><h2 id="captures" tabindex="-1">Captures <a class="header-anchor" href="#captures" aria-label="Permalink to &quot;Captures&quot;">​</a></h2><ul><li><p><strong>01-perf-catalogue-reel.png</strong> — caisse APPAIRÉE (base <code>pos.db</code>, catalogue réel du magasin, 4 produits + layout de boutons rapides), après des actions réelles : 6 boutons rapides, 3 taps liste, 5 « + / − », 4 scans douchette simulés (<code>adb shell input text 6191234567890</code> + Entrée), 10 frappes dans la recherche (« eau », « th », effacements).</p><table tabindex="0"><thead><tr><th>Action</th><th>n</th><th>p50</th><th>p95</th><th>max</th><th></th></tr></thead><tbody><tr><td>Scan → ligne</td><td>4</td><td>0,5 ms</td><td>1,5 ms</td><td>1,5 ms</td><td>✅</td></tr><tr><td>Recherche</td><td>10</td><td>5,9 ms</td><td>971,5 ms</td><td>971,5 ms</td><td>⚠️</td></tr><tr><td>Bouton rapide</td><td>6</td><td>0,0 ms</td><td>7,6 ms</td><td>7,6 ms</td><td>✅</td></tr><tr><td>Tap produit</td><td>3</td><td>0,0 ms</td><td>0,0 ms</td><td>0,0 ms</td><td>✅</td></tr><tr><td>Quantité ±</td><td>5</td><td>0,0 ms</td><td>0,1 ms</td><td>0,1 ms</td><td>✅</td></tr></tbody></table><p>Recherche : 8 frappes sur 10 sous 10 ms ; les 2 dépassements (704 ms et 972 ms) sont les premières frappes juste après l&#39;ouverture du clavier (IME et app sur le même vCPU affamé). Avec n = 10, p95 = max (rang le plus proche).</p></li><li><p><strong>02-catalogue-50k-recherche.png</strong> — démo « catalogue 50 000 produits » (base SÉPARÉE <code>perf-demo.db</code>, jamais <code>pos.db</code>), après « Charger le catalogue de référence » (semis hors thread principal : <strong>4 787 ms</strong>). Recherche « lait » : la liste est bornée et la ligne discrète « 100 premiers résultats — affinez la recherche » s&#39;affiche sous le champ.</p></li><li><p><strong>03-perf-catalogue-50k.png</strong> — écran Performance de la démo 50k (mesures remises à zéro avant la série) : 12 scans HID (<code>ReferenceCatalog.barcode(i)</code>, i = 12345, 40000, 7, 49999…), 17 frappes de recherche (« lait », « lait 001 », effacements, « eau »), 5 taps liste, 6 « + / − ».</p><table tabindex="0"><thead><tr><th>Action</th><th>n</th><th>p50</th><th>p95</th><th>max</th><th></th></tr></thead><tbody><tr><td>Scan → ligne</td><td>12</td><td>0,9 ms</td><td>1,6 ms</td><td>1,6 ms</td><td>✅</td></tr><tr><td>Recherche</td><td>17</td><td>1 767,3 ms</td><td>5 168,1 ms</td><td>5 168,1 ms</td><td>⚠️</td></tr><tr><td>Tap produit</td><td>5</td><td>0,1 ms</td><td>0,1 ms</td><td>0,1 ms</td><td>✅</td></tr><tr><td>Quantité ±</td><td>6</td><td>0,1 ms</td><td>0,2 ms</td><td>0,2 ms</td><td>✅</td></tr></tbody></table><p>Pas de bouton rapide ici : la base de démo n&#39;a pas de layout (aucun serveur pour en pousser un). Encaissement absent de la démo (ni session ni outbox).</p></li></ul><h2 id="ce-que-ca-prouve-ce-qui-reste" tabindex="-1">Ce que ça prouve / ce qui reste <a class="header-anchor" href="#ce-que-ca-prouve-ce-qui-reste" aria-label="Permalink to &quot;Ce que ça prouve / ce qui reste&quot;">​</a></h2><ul><li>Scan, tap liste, bouton rapide et quantité tiennent la promesse largement, y compris sur 50 000 produits et sur un émulateur affamé.</li><li><strong>La recherche sur 50 000 produits ne tient PAS le budget sur cet émulateur</strong> (p50 ≈ 1,8 s). La requête <code>searchActiveProducts</code> de <code>:shared</code> (<code>name LIKE &#39;%q%&#39;</code> parcouru par l&#39;index <code>(active, name)</code> jusqu&#39;à 100 résultats) mesurait 31 ms au pire cas sur simulateur iOS : l&#39;écart est surtout dû à la famine CPU, mais une saisie au préfixe / FTS5 et l&#39;annulation des recherches dépassées sont à envisager. À re-mesurer sur un vrai terminal milieu de gamme avant de conclure (hors périmètre de ce lot : <code>:shared</code> non modifié ici).</li><li>Mesures en mémoire seulement (fenêtre de 200 par action, perdue au redémarrage de l&#39;app) ; pas encore de télémétrie remontée au serveur.</li></ul><hr><h2 id="suite-analyse-et-correctifs-meme-jour-apres-le-premier-releve" tabindex="-1">Suite : analyse et correctifs (même jour, après le premier relevé) <a class="header-anchor" href="#suite-analyse-et-correctifs-meme-jour-apres-le-premier-releve" aria-label="Permalink to &quot;Suite : analyse et correctifs (même jour, après le premier relevé)&quot;">​</a></h2><p>La recherche ⚠️ du relevé ci-dessus a été analysée sur la base RÉELLE de l&#39;émulateur (<code>perf-demo.db</code> copiée sur le Mac). Plan SQLite correct (index <code>local_product_active_name</code>) et requête à <strong>10–20 ms</strong>, y compris le pire cas « zzzz ». Les secondes ne venaient donc pas de la requête seule. Quatre causes ont été trouvées et corrigées :</p><ol><li><strong><code>LIKE &#39;%q%&#39;</code> d&#39;Android</strong> (comparaison Unicode, coûteuse sur 50 000 lignes), remplacé par une colonne <code>name_norm</code> (minuscules, sans accents) et <code>instr()</code> dans <code>:shared</code> (migration <code>6.sqm</code>). Bonus RG-CAT-70 : la recherche devient insensible aux accents (<strong>04-recherche-sans-accent-pates.png</strong> : « pates » trouve « Pâtes 00009 », en réel sur l&#39;émulateur).</li><li><strong>Recherches empilées</strong> : chaque frappe lançait une recherche sans annuler la précédente. Désormais la dernière frappe gagne, et une recherche annulée n&#39;est jamais comptée. Un résultat périmé est aussi ignoré (course sur les threads IO parallèles).</li><li><strong>Scan perdu quand la recherche a le focus</strong> (vrai bug RG-HW-09). <strong>05-AVANT-scans-perdus-dans-recherche.png</strong> : 12 rafales finies dans le champ, aucun scan traité. Le clavier virtuel (IME) reçoit les touches AVANT <code>Activity.dispatchKeyEvent</code>. Correctif : interception <code>onPreInterceptKeyBeforeSoftKeyboard</code> à la racine, horodatage de la FRAPPE (<code>KeyEvent.eventTime</code>) au lieu de l&#39;heure de traitement, dédoublonnage des deux chemins. <strong>06-APRES-12-scans-recherche-focalisee.png</strong> : les 12 scans sont au panier, total <strong>52,946 TND</strong> = somme exacte des 12 prix (aucun caractère compté en double), champ nettoyé, liste par défaut.</li><li><strong>Chiffres du scan qui fuient dans la recherche</strong> : chacun lançait une requête SQLite non interruptible et le scan attendait derrière la file (p50 410 ms mesuré). La recherche est désormais suspendue pendant une rafale de douchette (≥ 3 touches à moins de 50 ms).</li></ol><h3 id="mesures-in-app-apres-correctifs-non-concluantes-sur-cette-machine" tabindex="-1">Mesures in-app après correctifs : NON concluantes sur cette machine <a class="header-anchor" href="#mesures-in-app-apres-correctifs-non-concluantes-sur-cette-machine" aria-label="Permalink to &quot;Mesures in-app après correctifs : NON concluantes sur cette machine&quot;">​</a></h3><p>Le Mac était à <strong>10 Go de swap</strong> pendant les relevés suivants (gels de plusieurs secondes, jusqu&#39;à un « scan » de 54 s). L&#39;injecteur <code>adb</code> lui-même est retardé entre deux caractères, ce qui casse les rafales simulées. Une vraie douchette horodate ses touches dans le noyau et ne subirait pas cela. Ces relevés ne sont pas publiés ici. <strong>À re-mesurer</strong> sur un émulateur au repos ou, mieux, sur un terminal milieu de gamme réel (l&#39;écran Performance existe aussi en mode appairé). La référence fiable reste le banc de <code>:shared</code> (50 000 produits, SQLite réel, JVM et simulateur iOS : tous les chemins à p95 ≤ 15 ms).</p></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/01-perf-catalogue-reel.png" target="_blank"><img src="'+n+'" alt="01-perf-catalogue-reel.png" loading="lazy"></a><figcaption>01-perf-catalogue-reel.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/02-catalogue-50k-recherche.png" target="_blank"><img src="'+o+'" alt="02-catalogue-50k-recherche.png" loading="lazy"></a><figcaption>02-catalogue-50k-recherche.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/03-perf-catalogue-50k.png" target="_blank"><img src="'+c+'" alt="03-perf-catalogue-50k.png" loading="lazy"></a><figcaption>03-perf-catalogue-50k.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/04-recherche-sans-accent-pates.png" target="_blank"><img src="'+d+'" alt="04-recherche-sans-accent-pates.png" loading="lazy"></a><figcaption>04-recherche-sans-accent-pates.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/05-AVANT-scans-perdus-dans-recherche.png" target="_blank"><img src="'+i+'" alt="05-AVANT-scans-perdus-dans-recherche.png" loading="lazy"></a><figcaption>05-AVANT-scans-perdus-dans-recherche.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-mesure-100ms-android/06-APRES-12-scans-recherche-focalisee.png" target="_blank"><img src="'+u+'" alt="06-APRES-12-scans-recherche-focalisee.png" loading="lazy"></a><figcaption>06-APRES-12-scans-recherche-focalisee.png</figcaption></figure></div>',5)])])}const _=r(l,[["render",p]]);export{A as __pageData,_ as default};
